CREATE TRIGGER Trigger_1494 AFTER DELETE ON hub_claim
   REFERENCING OLD TABLE AS OLDTABLE FOR EACH ROW

   WHEN (0 < (SELECT count(*) FROM sat_claim_sap, oldtable WHERE sat_claim_sap.claim_hash_key = oldtable.claim_hash_key))
  /* erwin Builtin Trigger */
